sys_script.script:
// Auto-calculates complaint priority based on the category.
// Priority: 1 (Critical), 2 (High), 3 (Moderate), 4 (Low)
(function autoCalculatePriority() {
    var category = current.getValue('category');

    // Only auto-set priority if not already set
    if (current.getValue('priority')) {
        return;
    }

    var priority = '4';

    switch (category) {
        case 'water_leak':
        case 'sewage':
            priority = '1';
            break;
        case 'pothole':
        case 'traffic':
            priority = '2';
            break;
        case 'streetlight':
        case 'noise':
            priority = '3';
            break;
        case 'trash':
        case 'graffiti':
        case 'park_damage':
        case 'other':
        default:
            priority = '4';
            break;
    }

    current.setValue('priority', priority);
})();
